const paths={crown:'M3 7l4 4 5-7 5 7 4-4-2 12H5ZM6 22h12',trend:'M3 17l6-6 4 4 8-10M15 5h6v6',briefcase:'M3 7h18v14H3ZM8 7V3h8v4M3 12l9 4 9-4',home:'M3 10 12 3l9 7v11h-6v-7H9v7H3Z',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',list:'M8 5h13M8 12h13M8 19h13M3 5h.01M3 12h.01M3 19h.01',user:'M20 21v-2a7 7 0 0 0-14 0v2M16 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0',tool:'m14 6 4 4M3 21l9-9M14 3a6 6 0 0 0-5 8l-6 6a3 3 0 0 0 4 4l6-6a6 6 0 0 0 8-8l-5 5-4-4 5-5Z',bolt:'m13 2-9 12h7l-1 8 10-12h-8Z',paint:'M3 3h14v6H3ZM17 6h4v7H10v8',clean:'m12 3 3 10M8 14l10-3 3 8-12 3-1-8Z',leaf:'M20 3C6 2 2 8 5 15c6 8 16 1 15-12ZM4 21 16 8',truck:'M1 5h13v12H1ZM14 9h5l4 5v3h-9M7 19a2 2 0 1 1-4 0 2 2 0 0 1 4 0M21 19a2 2 0 1 1-4 0 2 2 0 0 1 4 0',tech:'M3 3h18v13H3ZM8 21h8M12 16v5',book:'M12 5C8 2 4 3 2 4v16c3-2 7-2 10 0 3-2 7-2 10 0V4c-3-1-7-2-10 1ZM12 5v15',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',chart:'M3 3v18h19M7 16v-5M12 16V7M17 16v-9',shield:'m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6Zm-5 9 3 3 6-6'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.tool}"/></svg>`;
const services=[['Fontanería','tool','#eaf1fc','#597baa'],['Electricidad','bolt','#fff4dc','#c59635'],['Pintura','paint','#f0eaff','#9170b6'],['Limpieza','clean','#e7f5f0','#50977c'],['Jardinería','leaf','#eaf4e4','#709951'],['Mudanzas y armado','truck','#fff0e7','#c78253'],['Soporte tecnológico','tech','#e7f3f7','#548c9e'],['Clases particulares','book','#fcebf0','#b76d8a']];
let communityData={stats:[],unread:[],reviewed:[]};
let application=null,applications=[],applicationFilter='pending';
let pros=[],requests=[],accounts=[],currentUser=null,role='',page='home',category='',query='',filter='Todos',worker=null,available=true,canSetupAdmin=false,authEpoch=0;
let setupToken=new URL(location.href).searchParams.get('setup')||'';if(setupToken){history.replaceState(null,'',location.pathname);}
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const avatar=(photo,name)=>`<div class="person">${photo?`<button type="button" class="photo-open" data-view-photo aria-label="Ampliar foto de ${esc(name)}"><img class="avatar-photo" src="${esc(photo)}" alt="Foto de ${esc(name)}" loading="lazy"></button>`:esc(initials(name||'ServiMatch'))}</div>`;
const statusClass={'Pendiente':'pending','Asignado':'assigned','Confirmado':'confirmed','En curso':'progress','Completado':'completed','Cancelado':'cancelled'};
const badge=s=>`<span class="badge status-${statusClass[s]||'unknown'}">${esc(s)}</span>`;
const professionalStatus=p=>({available:{label:'Activo · Disponible',color:'available'},inactive:{label:'No disponible',color:'inactive'},busy:{label:'En servicio',color:'busy'}}[p.status|| (p.available?'available':'inactive')]);
const availabilityBadge=p=>{const s=professionalStatus(p);return `<span class="professional-status availability-${s.color}"><span class="status-dot" aria-hidden="true"></span>${s.label}</span>`};
const format=d=>new Intl.DateTimeFormat('es-SV',{day:'numeric',month:'short'}).format(new Date(d+'T12:00:00'));
const shortId=id=>id.slice(0,11).toUpperCase();
const initials=name=>name.split(/\s+/).slice(0,2).map(n=>n[0]).join('').toUpperCase();
async function api(path,body){const res=await fetch('/api/'+path,{method:body===undefined?'GET':'POST',headers:{...(body===undefined?{}:{'Content-Type':'application/json'}),...(setupToken?{'X-Setup-Token':setupToken}:{})},...(body===undefined?{}:{body:JSON.stringify(body)}),cache:'no-store',credentials:'same-origin'});let data;try{data=await res.json()}catch{throw new Error('No se pudo conectar con el servidor.')}if(!res.ok){const error=new Error(data.error||'No se pudo completar la operación.');error.status=res.status;if(res.status===401&&!['login','password'].includes(path))resetUi();throw error}return data}
function resetUi(){stopChat();authEpoch++;communityData={stats:[],unread:[],reviewed:[]};currentUser=null;application=null;applications=[];applicationFilter='pending';role='';pros=[];requests=[];accounts=[];page='home';category='';query='';filter='Todos';worker=null;if(modal.open)modal.close();document.querySelector('#modalBody').textContent='';document.querySelector('#account').textContent='—';document.querySelector('#roleLabel').textContent='';authScreen();}
async function refresh(){const epoch=authEpoch;const data=await api('state');if(epoch!==authEpoch)return;communityData=data.community||{stats:[],unread:[],reviewed:[]};currentUser=data.user;role=currentUser.role;application=data.application||null;applications=data.applications||[];pros=data.professionals;requests=data.requests;const mine=pros.find(p=>p.mine);worker=mine?.id;available=mine?.available??true;if(role==='admin'){const d=await api('accounts');if(epoch!==authEpoch)return;accounts=d.accounts}else accounts=[];render()}
function toast(t){const e=document.querySelector('#toast');e.textContent=t;e.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>e.style.display='none',4000)}
function show(html){stopChat();document.querySelector('#modalBody').innerHTML=`<div class="modal-head"><span class="eyebrow">SERVIMATCH</span><button class="close" data-close aria-label="Cerrar">×</button></div>${html}`;if(!modal.open)modal.showModal()}
const passwordFields=(confirm=true)=>`<label class="field">Contraseña<input name="password" type="password" autocomplete="new-password" required minlength="15" maxlength="128" placeholder="Mínimo 15 caracteres"></label>${confirm?'<label class="field">Confirmar contraseña<input name="confirmPassword" type="password" autocomplete="new-password" required minlength="15" maxlength="128"></label>':''}`;
function professionalFields(values={}){return `<div class="two"><label class="field">Especialidad<select name="service" required>${services.map(([s])=>`<option ${values.service===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="field">Tarifa desde (USD)<input name="price" type="number" min="0" max="10000" step="0.01" required value="${esc(values.price??'')}" placeholder="25.00"></label></div><label class="field">Zona donde trabajas<input name="zone" required minlength="2" maxlength="200" value="${esc(values.zone||'')}" placeholder="Ej. San Salvador y Santa Tecla"></label><label class="field">Experiencia<input name="experience" required minlength="2" maxlength="500" value="${esc(values.experience||'')}" placeholder="Ej. 3 años en instalaciones y reparaciones"></label><label class="field">Descripción de tus servicios<textarea name="bio" required minlength="10" maxlength="1000" placeholder="Cuéntanos cómo ayudas a tus clientes">${esc(values.bio||'')}</textarea></label>`}
function authScreen(mode='login'){
 document.body.classList.add('signed-out');document.querySelector('#mobileNav').innerHTML='';
 const choosing=mode==='register',registering=['register-client','register-worker'].includes(mode),professional=mode==='register-worker',setup=mode==='setup',changing=mode==='change';
 const title=choosing?'¿Cómo quieres usar ServiMatch?':professional?'Convierte tu talento en oportunidades.':registering?'Encuentra la ayuda que necesitas.':setup?'Configura tu administrador':changing?'Elige tu nueva contraseña':'Qué bueno tenerte aquí.';
 const subtitle=choosing?'Elige la opción que mejor describe lo que buscas.':professional?'Completa tu perfil para que nuestro equipo revise tu postulación.':registering?'Crea tu cuenta de cliente y solicita tu primer servicio.':setup?'Define tus credenciales de administración.':changing?'Cambia tu contraseña temporal para continuar.':'Inicia sesión con tu correo y contraseña de ServiMatch.';
 app.innerHTML=`<div class="auth-layout ${choosing?'auth-choose-layout':''}"><section class="auth-story"><a class="brand logo-brand" href="/" aria-label="ServiMatch, inicio"><img src="/logo.png" alt="ServiMatch" width="467" height="81"></a><div><span class="eyebrow">TU NECESIDAD. TU SOLUCIÓN.</span><h1>Conectamos ayuda.<br>Impulsamos talento.</h1><p>Una comunidad para encontrar soluciones<br>y construir nuevas oportunidades.</p><div class="auth-features"><span>${icon('shield')} Profesionales revisados por nuestro equipo</span><span>${icon('tool')} Talento de El Salvador</span></div></div><small>Tu necesidad. Tu solución. Tu oportunidad.</small></section><section class="auth-form ${professional?'professional-registration':''}"><span class="eyebrow">BIENVENIDO A SERVIMATCH</span><h2>${title}</h2><p class="sub">${subtitle}</p>${choosing?`<div class="role-choices"><button type="button" class="role-choice" data-auth="register-client"><span class="role-symbol">${icon('home')}</span><strong>Necesito un servicio</strong><span>Encuentra profesionales y solicita ayuda para tu hogar o negocio.</span><b>Crear cuenta de cliente →</b></button><button type="button" class="role-choice" data-auth="register-worker"><span class="role-symbol">${icon('tool')}</span><strong>Quiero ofrecer mis servicios</strong><span>Comparte tu experiencia y postúlate para formar parte del equipo.</span><b>Postularme como profesional →</b></button></div>`:`<form id="${setup?'adminSetupForm':changing?'forcedPasswordForm':registering?'registerForm':'loginForm'}">${registering?`<input type="hidden" name="role" value="${professional?'worker':'client'}">`:''}${registering||setup?'<label class="field">Nombre completo<input name="name" autocomplete="name" required minlength="2" maxlength="80"></label>':''}${!changing?'<label class="field">Correo electrónico<input name="email" type="email" autocomplete="username" required maxlength="254" placeholder="tu@correo.com"></label>':`<div class="identity-chip">${icon('user')} ${esc(currentUser?.email||'')}</div><label class="field">Contraseña temporal o actual<input name="currentPassword" type="password" autocomplete="current-password" required maxlength="128"></label>`}${registering?'<label class="field">Teléfono de contacto<input name="phone" type="tel" autocomplete="tel" required pattern="[+0-9 ()-]{8,20}" maxlength="20" placeholder="7000-0000"></label>':''}${mode==='login'?'<label class="field">Contraseña<input name="password" type="password" autocomplete="current-password" required maxlength="128" placeholder="Tu contraseña"></label>':passwordFields()}${professional?professionalFields():''}${professional?'<p class="notice">Tu perfil quedará pendiente de aprobación. El administrador revisará tus datos antes de habilitarte para recibir trabajos.</p>':''}<button class="btn wide" type="submit">${setup?'Crear acceso de administrador':changing?'Guardar nueva contraseña':professional?'Enviar mi postulación':registering?'Crear cuenta de cliente':'Iniciar sesión →'}</button><div class="form-error" role="alert"></div></form>`}${changing?'<button type="button" class="text-button wide" data-logout>Cerrar sesión</button>':`<div class="auth-divider">${mode==='login'?'¿Es tu primera visita?':'¿Ya tienes una cuenta?'}</div><button type="button" class="btn outline wide" data-auth="${mode==='login'?'register':'login'}">${mode==='login'?'Crear una cuenta':'Volver a iniciar sesión'}</button>${registering?'<button type="button" class="text-button wide" data-auth="register">← Cambiar tipo de registro</button>':''}`}${mode==='login'&&canSetupAdmin?'<button type="button" class="text-button wide" data-auth="setup">Configurar administrador inicial</button>':''}<p class="auth-note">Cada cuenta tiene su propio rol. La administración de la plataforma permanece reservada.</p></section></div>`;
}
async function boot(){const epoch=authEpoch;app.innerHTML='<div class="empty">Conectando con ServiMatch…</div>';try{const d=await api('me');if(epoch!==authEpoch)return;canSetupAdmin=d.canSetupAdmin;currentUser=d.user;if(!currentUser){authScreen(setupToken&&canSetupAdmin?'setup':'login');return}if(currentUser.mustChangePassword){authScreen('change');return}await refresh()}catch(e){app.innerHTML=`<div class="card empty"><h2>No pudimos cargar la app</h2><p>${esc(e.message)}</p><button class="btn" data-retry>Reintentar</button></div>`}}
function broadcastAuth(){try{localStorage.setItem('servimatch-auth-event',String(Date.now()))}catch{}}
let loggingOut=false;
async function logout(){if(loggingOut)return;loggingOut=true;document.querySelectorAll('[data-logout]').forEach(b=>b.disabled=true);try{authEpoch++;await api('logout',{});resetUi();broadcastAuth();toast('Sesión cerrada. Ingresa tus credenciales para volver a entrar.')}finally{loggingOut=false;document.querySelectorAll('[data-logout]').forEach(b=>b.disabled=false)}}
function nav(){document.body.classList.remove('signed-out');const items=application?[['home','clock','Mi postulación'],['profile','user','Mi perfil']]:role==='client'?[['home','home','Inicio'],['explore','search','Explorar'],['requests','list','Mis servicios'],['profile','user','Mi perfil']]:role==='worker'?[['home','home','Mi jornada'],['requests','list','Mis trabajos'],['specialty','search','Mi especialidad'],['profile','user','Mi perfil']]:[['home','chart','Resumen'],['requests','list','Solicitudes'],['team','user','Profesionales'],['applications','shield','Postulaciones'],['accounts','shield','Cuentas'],['profile','shield','Administración']];const html=items.map(([id,i,t])=>`<button data-page="${id}" class="${page===id?'active':''}">${icon(i)}${t}${id==='applications'&&applications.some(a=>a.approvalStatus==='pending')?'<span class="nav-count">'+applications.filter(a=>a.approvalStatus==='pending').length+'</span>':''}</button>`).join('');document.querySelector('#desktopNav').innerHTML=html;document.querySelector('#mobileNav').innerHTML=html;document.querySelector('#roleTitle').textContent={client:'MI HOGAR, EN BUENAS MANOS',worker:'TU TALENTO HACE LA DIFERENCIA',admin:'CENTRO DE OPERACIONES'}[role];document.querySelector('#account').innerHTML=currentUser.photo?`<img class="avatar-photo" src="${esc(currentUser.photo)}" alt="Mi perfil">`:esc(initials(currentUser.name));document.querySelector('#roleLabel').textContent=application?'Profesional · En revisión':{client:'Cliente',worker:'Profesional',admin:'Administrador'}[role]}
function proCard(p){return `<article class="card"><div class="pro-top">${avatar(p.photo,p.name)}<div><h3>${esc(p.name)}</h3><p>${esc(p.service)}</p></div></div><div class="rating">${availabilityBadge(p)}<p>${trustSummary(p)}</p></div><div class="pro-foot"><span class="price"><small>Desde</small>$${Number(p.price).toFixed(2)}</span><button class="btn secondary" data-pro="${p.id}">Ver perfil</button></div></article>`}
function categories(){return `<div class="categories">${services.map(([s,i,t,c])=>`<button class="category ${category===s?'selected':''}" data-category="${s}"><span class="symbol" style="--tint:${t};--color:${c}">${icon(i)}</span><span><strong>${s}</strong><small>Encontrar ayuda</small></span></button>`).join('')}</div>`}
function matchedPros(){return pros.filter(p=>(!category||category===p.service)&&(`${p.name} ${p.service}`.toLocaleLowerCase('es').includes(query.toLocaleLowerCase('es'))))}
function clientHome(explore=false){let filtered=matchedPros(),active=requests.find(r=>!['Completado','Cancelado'].includes(r.status));app.innerHTML=`<h1>${explore?'Encuentra a tu profesional':`Hola, ${esc(currentUser.name.split(' ')[0])} <span style="font-size:26px">✦</span>`}</h1><p class="sub">${explore?'Talento local para lo que necesitas.':'Un poco de ayuda. Mucha tranquilidad.'}</p>${!explore?`<section class="hero"><div><div class="tag">TU HOGAR MERECE ESTAR BIEN</div><h2>Lo que necesitas,<br>a un match de distancia.</h2><p>Encuentra la ayuda indicada y deja el resto en buenas manos.</p></div><div class="hero-art" aria-hidden="true"><div class="house"></div><span class="art-check">✓</span></div></section>`:''}<label class="search">${icon('search')}<input id="search" placeholder="¿Qué servicio necesitas hoy?" aria-label="Buscar servicios o profesionales" value="${esc(query)}"></label><div class="section-head"><div><h2>¿En qué te ayudamos?</h2><p>Soluciones para tu hogar y tu negocio</p></div>${category?'<button class="text-button" data-clear>Ver todo</button>':''}</div>${categories()}<div class="layout"><section><div class="section-head"><div><h2>${category||'Personas que resuelven'}</h2><p>Conoce a los profesionales de nuestra comunidad</p></div></div><div class="pros" id="pros">${(explore||category||query?filtered:filtered.slice(0,4)).map(proCard).join('')||'<div class="card empty">Todavía no hay profesionales en esta categoría. Vuelve a consultar pronto.</div>'}</div></section><aside class="right-column"><div class="card active-card"><div class="mini-title">TU PRÓXIMO SERVICIO</div>${active?`<h3>${esc(active.service)}</h3>${badge(active.status)}<p>${format(active.date)} · ${esc(active.time)}<br>${esc(pros.find(p=>p.id===active.pro)?.name||'Por asignar')}</p><button class="btn outline wide" data-request="${active.id}">Ver seguimiento ${icon('clock')}</button>`:'<h3>Tu próxima solución empieza aquí</h3><p>Elige una categoría para solicitar tu primer servicio.</p>'}</div><div class="card help-card"><h3>Una comunidad en la que confías</h3><p>Consulta el perfil y los detalles del servicio antes de confirmar.</p><button class="text-button" data-help>¿Cómo funciona? →</button></div></aside></div>`}
function requestCard(r){let p=pros.find(p=>p.id===r.pro);return `<article class="card request">${role==='client'?avatar(p?.photo,p?.name):avatar(r.clientPhoto,r.client)}<div class="body"><span class="mini-title">${shortId(r.id)} · ${format(r.date)} · ${esc(r.time)}</span><h3>${esc(r.service)}</h3><p>${role==='client'?esc(p?.name||'Profesional por asignar'):esc(r.client)}</p><p>${esc(r.description)}</p></div><div>${badge(r.status)}</div><div class="request-actions"><button class="btn secondary" data-request="${r.id}">Ver detalles</button>${chatButton(r)}</div></article>`}
function requestsPage(){app.innerHTML=`<h1>${role==='client'?'Mis servicios':role==='worker'?'Mis trabajos':'Todas las solicitudes'}</h1><p class="sub">Consulta los detalles y el avance de cada servicio.</p><div class="filters">${['Todos','Pendiente','Asignado','Confirmado','En curso','Completado','Cancelado'].map(s=>`<button data-filter="${s}" class="${filter===s?'selected':''}">${s}</button>`).join('')}</div>${requests.filter(r=>(role!=='worker'||r.pro===worker)&&(filter==='Todos'||r.status===filter)).map(requestCard).join('')||'<div class="card empty">No hay servicios en este estado.</div>'}`}
function stats(items){return `<div class="stats">${items.map(([label,n,detail])=>`<div class="stat"><span>${label}</span><strong>${n}</strong><span>${detail}</span></div>`).join('')}</div>`}
function adminHome(){app.innerHTML=`<h1>Todo en su lugar.</h1><p class="sub">Una mirada a la actividad de ServiMatch</p>${stats([['Solicitudes totales',requests.length,'Registradas en la plataforma'],['Servicios activos',requests.filter(r=>!['Completado','Cancelado'].includes(r.status)).length,'Pendientes de finalizar'],['Completados',requests.filter(r=>r.status==='Completado').length,'Servicios finalizados'],['Profesionales',pros.length,'Registrados por administración']])}<div class="section-head"><div><h2>Tu equipo, bien conectado.</h2><p>Da de alta a los profesionales que prestarán los servicios.</p></div><button class="btn" data-add-pro>+ Registrar profesional</button></div><div class="card applications-summary"><div><h3>${applications.filter(a=>a.approvalStatus==='pending').length} postulaciones pendientes</h3><p>Revisa el talento que quiere formar parte de ServiMatch.</p></div><button class="btn secondary" data-page="applications">Revisar postulaciones →</button></div><div class="section-head"><h2>Actividad reciente</h2><button class="text-button" data-page="requests">Ver todas →</button></div>${requests.slice(0,5).map(requestCard).join('')||'<div class="card empty">Todavía no hay solicitudes. Los clientes podrán crearlas cuando registres profesionales.</div>'}`}
function workerHome(){const specialty=pros.find(p=>p.mine)?.service||'';app.innerHTML=`<div class="availability"><div><h1>Hola, ${esc(currentUser.name.split(' ')[0])} ✦</h1><p class="sub">Tu especialidad: ${esc(specialty)}</p></div><div class="professional-controls">${pros.find(p=>p.mine)?.status==='busy'?availabilityBadge(pros.find(p=>p.mine)):''}<button class="btn availability-toggle availability-${available?'available':'inactive'}" data-available aria-pressed="${available}"><span class="status-dot" aria-hidden="true"></span>${available?'Activo · Disponible':'No disponible'}</button></div></div>${stats([['Por confirmar',requests.filter(r=>r.status==='Asignado').length,'Solicitudes asignadas'],['En tu agenda',requests.filter(r=>['Confirmado','En curso'].includes(r.status)).length,'Servicios activos'],['Completados',requests.filter(r=>r.status==='Completado').length,'Servicios finalizados'],['Especialidad',pros.find(p=>p.mine)?.service||'—','Tu talento en acción']])}<div class="section-head"><div><h2>Tu agenda de servicios</h2><p>Consulta al cliente, la dirección y el trabajo solicitado</p></div></div>${requests.filter(r=>r.pro===worker&&!['Completado','Cancelado'].includes(r.status)).map(requestCard).join('')||'<div class="card empty">No tienes servicios activos. Las asignaciones del administrador aparecerán aquí.</div>'}<div class="section-head"><div><h2>Solicitudes de tu especialidad</h2><p>Solo ${esc(specialty)} · Los datos de contacto se muestran al asignarte el trabajo.</p></div><button class="text-button" data-page="specialty">Ver solicitudes →</button></div>${requests.filter(r=>r.redacted).slice(0,3).map(requestCard).join('')||'<div class="card empty">No hay nuevas solicitudes de tu especialidad.</div>'}`}
function profile(){app.innerHTML=`<h1>${role==='admin'?'Administración':'Mi perfil'}</h1><p class="sub">Tu espacio dentro de ServiMatch</p><div class="card profile-card"><div class="pro-top">${avatar(currentUser.photo,currentUser.name)}<div><h3>${esc(currentUser.name)}</h3><p>${esc(currentUser.email)}</p></div></div><label class="btn secondary photo-picker">Agregar o cambiar foto<input id="profilePhoto" type="file" accept="image/jpeg,image/png,image/webp" hidden></label><button class="text-button" data-remove-photo>Quitar foto</button><p class="sub">JPG, PNG o WebP, hasta 8 MB. Se ajusta automáticamente.</p><div class="details" style="margin-top:22px"><strong>Rol:</strong> ${{client:'Cliente',worker:'Profesional',admin:'Administrador'}[role]}<br><strong>Teléfono:</strong> ${esc(currentUser.phone||'No registrado')}</div>${role==='admin'?'<p>Revisa las postulaciones de profesionales o registra a alguien directamente.</p><button class="btn wide" data-add-pro>Registrar profesional</button>':''}${role==='worker'&&!application?'<button class="btn wide" data-edit-public-profile>Completar mi perfil profesional</button>':''}${premiumCard()}<h3 style="font-size:14px;margin-top:25px">Pensada para acompañarte</h3><p class="sub">Abre la app desde Android o iPhone y agrégala a tu pantalla de inicio.</p><button class="btn secondary" data-install>Cómo instalar</button><p style="margin-top:28px"><button class="btn secondary wide" data-change-password>Cambiar contraseña</button></p><p><button class="btn outline wide" data-logout>Cerrar sesión</button></p></div>`}
function render(){nav();if(application&&page!=='profile'){applicationPage();return}if(page==='applications'&&role==='admin')applicationsPage();else if(page==='accounts'&&role==='admin')accountsPage();else if(page==='specialty'&&role==='worker')specialtyPage();else if(page==='profile')profile();else if(page==='requests')requestsPage();else if(page==='team'){app.innerHTML=`<div class="section-head"><div><h1>El talento de ServiMatch</h1><p class="sub">Profesionales aprobados en ServiMatch</p></div><button class="btn" data-add-pro>+ Registrar profesional</button></div><div class="pros">${pros.map(proCard).join('')||'<div class="card empty">Registra al primer profesional para comenzar.</div>'}</div>`}else if(role==='admin')adminHome();else if(role==='worker')workerHome();else clientHome(page==='explore')}
function details(id){const r=requests.find(r=>r.id===id);if(!r)return;const p=pros.find(p=>p.id===r.pro);const terminal=['Completado','Cancelado'].includes(r.status);show(`<span class="mini-title">${shortId(r.id)}</span><h2 style="margin:12px 0">${esc(r.service)}</h2>${badge(r.status)}<div class="service-actions">${chatButton(r)}${reviewButton(r)}</div><p>${esc(r.description)}</p><div class="service-people"><div class="service-person">${avatar(r.clientPhoto,r.client)}<div><span class="eyebrow">CLIENTE</span><strong>${esc(r.client)}</strong></div></div>${p?`<div class="service-person">${avatar(p.photo,p.name)}<div><span class="eyebrow">PROFESIONAL</span><strong>${esc(p.name)}</strong></div></div>`:''}</div><div class="details"><strong>Cliente:</strong> ${esc(r.client)}<br>${r.redacted?'Los datos de contacto se habilitan al asignarte el trabajo.<br>':'<strong>Teléfono:</strong> '+esc(r.phone)+'<br><strong>Dirección:</strong> '+esc(r.address)+'<br>'}<strong>Fecha:</strong> ${format(r.date)} · ${esc(r.time)}<br><strong>Profesional:</strong> ${esc(p?.name||'Pendiente de asignación')}${r.suggestedPro&&!r.pro?'<br><strong>Preferencia del cliente:</strong> '+esc(pros.find(p=>p.id===r.suggestedPro)?.name):''}</div><div class="timeline">${r.history.map(h=>`<div class="done">${esc(h.status)}<small>${new Date(h.at).toLocaleString('es-SV',{timeZone:'America/El_Salvador'})}</small></div>`).join('')}</div>${role==='admin'&&['Pendiente','Asignado'].includes(r.status)?`<form id="assignForm" data-id="${r.id}"><label class="field">Asignar profesional<select name="professional" required>${pros.filter(p=>p.service===r.service&&p.available).map(p=>`<option value="${p.id}" ${p.id===(r.pro||r.suggestedPro)?'selected':''}>${esc(p.name)} · ${esc(p.service)}</option>`).join('')}</select></label><button class="btn wide">${r.pro?'Confirmar asignación':'Asignar servicio'}</button></form>`:''}${role==='worker'&&!terminal?`<div class="two">${r.status==='Asignado'&&r.pro===worker?`<button class="btn" data-status="Confirmado" data-id="${r.id}">Aceptar trabajo</button><button class="btn outline" data-status="Pendiente" data-id="${r.id}">Devolver asignación</button>`:r.status==='Confirmado'?`<button class="btn wide" data-status="En curso" data-id="${r.id}">Iniciar servicio</button>`:r.status==='En curso'?`<button class="btn wide" data-status="Completado" data-id="${r.id}">Finalizar servicio</button>`:''}</div>`:''}${role==='client'&&['Pendiente','Asignado','Confirmado'].includes(r.status)?`<button class="text-button" data-cancel="${r.id}">Cancelar solicitud</button>`:''}`)}
async function proDetails(id){const p=pros.find(p=>p.id===Number(id));if(!p)return;const epoch=authEpoch;const extended=await api(`professionals/${p.id}/profile`);if(epoch!==authEpoch)return;show(`<div class="pro-top">${avatar(p.photo,p.name)}<div><h2>${esc(p.name)}</h2><p>${esc(p.service)}</p></div></div><div class="rating">${availabilityBadge(p)}<p>${trustSummary(p)}</p></div><p>${esc(p.bio)}</p>${publicProfileExtras(extended)}<div class="details">${p.zone?'<strong>Zona:</strong> '+esc(p.zone)+'<br>':''}${p.experience?'<strong>Experiencia:</strong> '+esc(p.experience)+'<br>':''}Precio orientativo desde <strong>$${Number(p.price).toFixed(2)} USD</strong><br>El costo final se acuerda antes de realizar el trabajo.${role==='admin'?'<br><strong>Correo:</strong> '+esc(p.email)+'<br><strong>Teléfono:</strong> '+esc(p.phone):''}</div><p class="notice">${p.available?'Disponible para recibir solicitudes.':'Este profesional no está disponible actualmente.'}</p>${role==='client'?`<button class="btn wide" data-book="${p.id}" ${p.available?'':'disabled'}>Solicitar este servicio</button>`:`<button class="btn secondary wide" data-close>Cerrar perfil</button>`}`)}
function booking(id){const p=pros.find(p=>p.id===Number(id)),today=new Date().toLocaleDateString('en-CA',{timeZone:'America/El_Salvador'});show(`<h2>Cuéntanos qué necesitas</h2><p class="sub">${esc(p.service)} · ${esc(p.name)}</p><form id="bookingForm" data-pro="${p.id}"><div class="details"><strong>Cliente:</strong> ${esc(currentUser.name)}<br><strong>Teléfono:</strong> ${esc(currentUser.phone)}</div><label class="field">Dirección del servicio<input name="address" required minlength="5" maxlength="200" autocomplete="street-address" placeholder="Dirección y punto de referencia"></label><div class="two"><label class="field">Fecha<input type="date" name="date" required min="${today}"></label><label class="field">Hora<input type="time" name="time" required></label></div><label class="field">Detalles del trabajo<textarea name="description" required minlength="10" maxlength="1000" placeholder="Describe el servicio que necesitas..."></textarea></label><p class="notice">El administrador revisará tu solicitud y asignará al profesional. Esta solicitud no genera cobros.</p><button class="btn wide">Crear solicitud</button><div class="form-error" role="alert"></div></form>`)}
function addProfessional(){if(role!=='admin')return;show(`<h2>Un nuevo talento en el equipo</h2><p class="sub">Registro de profesionales · Solo administración</p><form id="professionalForm"><label class="field">Nombre completo<input name="name" required minlength="2" maxlength="80" autocomplete="off"></label><label class="field">Correo de acceso<input name="email" type="email" required maxlength="254" autocomplete="off" placeholder="profesional@ejemplo.com"></label><label class="field">Contraseña temporal<input name="password" type="password" autocomplete="new-password" required minlength="15" maxlength="128" placeholder="Mínimo 15 caracteres"></label><label class="field">Teléfono<input name="phone" type="tel" required pattern="[+0-9 ()-]{8,20}" maxlength="20" placeholder="7000-0000"></label><div class="two"><label class="field">Especialidad<select name="service" required>${services.map(([s])=>`<option>${s}</option>`).join('')}</select></label><label class="field">Tarifa desde (USD)<input name="price" type="number" min="0" max="10000" step="0.01" required placeholder="25.00"></label></div><label class="field">Descripción del perfil<textarea name="bio" required minlength="10" maxlength="1000" placeholder="Experiencia y servicios que ofrece..."></textarea></label><p class="notice">Comparte el correo y la contraseña temporal con el profesional de forma privada. Deberá cambiarla en su primer acceso.</p><button class="btn wide">Registrar profesional</button><div class="form-error" role="alert"></div></form>`)}
function specialtyPage(){const specialty=pros.find(p=>p.mine)?.service||'';app.innerHTML=`<h1>Tu especialidad, tu espacio.</h1><p class="sub">${esc(specialty)} · Solo ves solicitudes relacionadas con tu especialidad.</p>${requests.filter(r=>r.service===specialty).map(requestCard).join('')||'<div class="card empty">No hay solicitudes de tu especialidad.</div>'}`}
function accountsPage(){app.innerHTML=`<h1>Cuentas de ServiMatch</h1><p class="sub">Gestiona el acceso de clientes y profesionales. Una clave temporal invalida las sesiones anteriores.</p>${accounts.map(u=>`<article class="card request">${avatar(u.photo,u.name)}<div class="body"><h3>${esc(u.name)}</h3><p>${esc(u.email)}</p><p>${{client:'Cliente',worker:'Profesional',admin:'Administrador'}[u.role]} · ${u.hasPassword?(u.mustChangePassword?'Cambio de contraseña pendiente':'Acceso configurado'):'Necesita contraseña inicial'}</p></div>${u.role!=='admin'?`<button class="btn secondary" data-reset-password="${u.id}">Asignar clave temporal</button>`:''}</article>`).join('')}`}
function passwordForm(accountId){if(accountId){const u=accounts.find(u=>u.id===accountId);if(!u)return;show(`<h2>Asignar contraseña temporal</h2><p>${esc(u.name)} · ${esc(u.email)}</p><form id="resetPasswordForm" data-id="${u.id}">${passwordFields()}<p class="notice">Se cerrarán las sesiones de esta cuenta. La persona deberá cambiar la contraseña en su próximo acceso.</p><button class="btn wide" type="submit">Guardar contraseña temporal</button><div class="form-error" role="alert"></div></form>`)}else show(`<h2>Cambiar tu contraseña</h2><form id="passwordForm"><label class="field">Contraseña actual<input name="currentPassword" type="password" autocomplete="current-password" required maxlength="128"></label>${passwordFields()}<button class="btn wide" type="submit">Guardar contraseña</button><div class="form-error" role="alert"></div></form>`)}
const applicationBadge=a=>`<span class="badge status-${{pending:'pending',approved:'completed',rejected:'cancelled'}[a.approvalStatus]||'unknown'}">${{pending:'Pendiente de aprobación',approved:'Aprobada',rejected:'No aprobada'}[a.approvalStatus]||'En revisión'}</span>`;
function applicationPage(){const rejected=application.approvalStatus==='rejected';app.innerHTML=`<h1>${rejected?'Tu talento puede dar el siguiente paso.':'Tu postulación está en camino.'}</h1><p class="sub">Hola, ${esc(currentUser.name.split(' ')[0])}. Aquí puedes seguir la revisión de tu perfil profesional.</p><article class="card application-self"><div class="application-heading"><span class="application-symbol">${icon(rejected?'tool':'clock')}</span>${applicationBadge(application)}</div><h2>${esc(application.service)}</h2><p>${rejected?'Nuestro equipo revisó tu perfil. Actualiza los datos indicados y vuelve a enviarlo.':'Nuestro equipo revisará tu experiencia y los servicios que ofreces. Cuando te aprueben, podrás recibir asignaciones y aparecerás en el catálogo.'}</p>${rejected?`<div class="review-feedback"><strong>Observación del administrador</strong><p>${esc(application.reviewNote)}</p></div>`:''}<div class="application-facts"><div><span>Zona de trabajo</span><strong>${esc(application.zone)}</strong></div><div><span>Experiencia</span><strong>${esc(application.experience)}</strong></div><div><span>Tarifa desde</span><strong>$${Number(application.price).toFixed(2)}</strong></div></div><p>${esc(application.bio)}</p><div class="application-actions"><button class="btn" data-edit-application>${rejected?'Corregir y reenviar':'Editar mi postulación'}</button><button class="btn secondary" data-check-application>Consultar estado</button></div></article>`}
function editApplication(){show(`<h2>Tu perfil profesional</h2><p class="sub">Al guardar, tu postulación volverá a quedar pendiente de revisión.</p><form id="applicationForm">${professionalFields(application)}<button class="btn wide" type="submit">Guardar y enviar para revisión</button><div class="form-error" role="alert"></div></form>`)}
function applicationsPage(){const visible=applications.filter(a=>applicationFilter==='all'||a.approvalStatus===applicationFilter);app.innerHTML=`<h1>Talento que quiere sumarse.</h1><p class="sub">Revisa cada perfil antes de habilitarlo para ofrecer servicios.</p><div class="filters">${[['pending','Pendientes'],['approved','Aprobadas'],['rejected','No aprobadas'],['all','Todas']].map(([value,label])=>`<button class="${applicationFilter===value?'selected':''}" data-application-filter="${value}">${label} (${applications.filter(a=>value==='all'||a.approvalStatus===value).length})</button>`).join('')}</div><div class="applications-list">${visible.map(a=>`<article class="card application-row">${avatar(a.photo,a.name)}<div class="application-info"><h3>${esc(a.name)}</h3><p>${esc(a.service)} · ${esc(a.zone||'Zona no indicada')}</p><small>${esc(a.email)}</small></div>${applicationBadge(a)}<button class="btn secondary" data-review-application="${a.id}">Revisar perfil</button></article>`).join('')||'<div class="card empty">No hay postulaciones en este estado.</div>'}</div>`}
function reviewApplication(id){const a=applications.find(a=>a.id===Number(id));if(!a)return;show(`<div class="pro-top">${avatar(a.photo,a.name)}<div><h2>${esc(a.name)}</h2><p class="sub">${esc(a.service)}</p></div></div>${applicationBadge(a)}<div class="details" style="margin:18px 0"><strong>Correo:</strong> ${esc(a.email)}<br><strong>Teléfono:</strong> ${esc(a.phone)}<br><strong>Zona:</strong> ${esc(a.zone||'No indicada')}<br><strong>Experiencia:</strong> ${esc(a.experience||'No indicada')}<br><strong>Tarifa desde:</strong> $${Number(a.price).toFixed(2)}</div><p>${esc(a.bio)}</p>${a.reviewNote?`<div class="review-feedback"><strong>Observación</strong><p>${esc(a.reviewNote)}</p></div>`:''}${a.approvalStatus==='pending'?`<div class="two"><button class="btn" data-application-decision="approve" data-id="${a.id}">Aprobar profesional</button><button class="btn outline" data-application-decision="reject" data-id="${a.id}">No aprobar</button></div>`:''}`)}
function applicationDecision(id,action){const a=applications.find(a=>a.id===Number(id));if(!a)return;show(`<h2>${action==='approve'?'Aprobar profesional':'Revisar observaciones'}</h2><p>${esc(a.name)} · ${esc(a.service)}</p><form id="reviewForm" data-id="${a.id}" data-version="${a.version}" data-action="${action}">${action==='reject'?'<label class="field">Motivo y recomendaciones<textarea name="reason" required minlength="5" maxlength="500" placeholder="Explica qué debe corregir o completar..."></textarea></label>':'<p>Su perfil aparecerá para los clientes y podrá recibir servicios de su especialidad.</p>'}<button class="btn wide" type="submit">${action==='approve'?'Confirmar aprobación':'Guardar revisión'}</button><div class="form-error" role="alert"></div></form>`)}
function installHelp(){show('<h2>Lleva ServiMatch contigo</h2><p><strong>Android:</strong> abre la app en Chrome y busca “Instalar app” o “Agregar a pantalla principal” en el menú.</p><p><strong>iPhone:</strong> abre el enlace en Safari, toca Compartir y luego “Agregar a pantalla de inicio”.</p><p class="notice">Necesitas conexión para iniciar sesión y gestionar servicios. Los registros se guardan en el servidor.</p>')}
async function changeStatus(id,status){await api(`requests/${id}/transition`,{status});modal.close();await refresh();toast('Solicitud actualizada: '+status)}
document.addEventListener('click',async e=>{const photo=e.target.closest('img.avatar-photo')||e.target.closest('[data-view-photo]')?.querySelector('img');if(photo){openPhoto(photo.getAttribute('src'),photo.getAttribute('alt'));return}const b=e.target.closest('button');if(!b)return;try{if(b.dataset.chat)await openChat(b.dataset.chat);else if(b.dataset.reviewService)reviewService(b.dataset.reviewService);else if(b.hasAttribute('data-edit-public-profile'))await editPublicProfile();else if(b.hasAttribute('data-add-portfolio'))addPortfolioItem();else if(b.dataset.removePortfolio){portfolioDraft.splice(Number(b.dataset.removePortfolio)-1,1);renderPortfolioDraft()}else if(b.hasAttribute('data-premium'))premiumDetails();else if(b.hasAttribute('data-demo-checkout'))demoCheckout();else if(b.hasAttribute('data-cancel-premium')){await api('subscription',{action:'cancel'});modal.close();await refresh();toast('Suscripción demo cancelada')}else if(b.hasAttribute('data-remove-photo')){await api('profile/photo',{photo:''});await refresh()}else if(b.hasAttribute('data-edit-application'))editApplication();else if(b.hasAttribute('data-check-application')){await refresh();toast(application?'Estado actualizado.':'Tu perfil ya está aprobado.')}else if(b.dataset.applicationFilter){applicationFilter=b.dataset.applicationFilter;applicationsPage()}else if(b.dataset.reviewApplication)reviewApplication(b.dataset.reviewApplication);else if(b.dataset.applicationDecision)applicationDecision(b.dataset.id,b.dataset.applicationDecision);else if(b.hasAttribute('data-logout')){await logout()}else if(b.dataset.auth){authScreen(b.dataset.auth)}else if(b.hasAttribute('data-change-password'))passwordForm();else if(b.dataset.resetPassword)passwordForm(b.dataset.resetPassword);else if(b.hasAttribute('data-close'))modal.close();else if(b.dataset.page){page=b.dataset.page;filter='Todos';render();window.scrollTo(0,0)}else if(b.hasAttribute('data-category')){category=category===b.dataset.category?'':b.dataset.category;render()}else if(b.hasAttribute('data-clear')){category='';query='';render()}else if(b.dataset.pro)await proDetails(b.dataset.pro);else if(b.dataset.book)booking(b.dataset.book);else if(b.dataset.request)details(b.dataset.request);else if(b.dataset.filter){filter=b.dataset.filter;render()}else if(b.dataset.status){b.disabled=true;await changeStatus(b.dataset.id,b.dataset.status)}else if(b.dataset.cancel)show(`<h2>¿Cancelar esta solicitud?</h2><p>El servicio quedará marcado como cancelado.</p><button class="btn wide" data-status="Cancelado" data-id="${b.dataset.cancel}">Confirmar cancelación</button>`);else if(b.hasAttribute('data-available')){await api('availability',{available:!available});await refresh();toast('Disponibilidad actualizada')}else if(b.hasAttribute('data-add-pro'))addProfessional();else if(b.hasAttribute('data-help'))show('<h2>De tu necesidad a la solución.</h2><p>1. Explora una categoría y revisa el perfil.</p><p>2. Envía una solicitud con fecha y detalles.</p><p>3. El administrador asigna el trabajo.</p><p>4. El profesional acepta, inicia y finaliza el servicio.</p>');else if(b.hasAttribute('data-install')||b.id==='install')installHelp();else if(b.id==='account'){page='profile';render()}else if(b.hasAttribute('data-retry'))await boot();else if(b.id==='refresh'){await refresh();toast('Datos actualizados')}}catch(error){toast(error.message);b.disabled=false}});
document.addEventListener('submit',async e=>{if(e.target.id!=='demoPaymentForm')return;e.preventDefault();e.stopImmediatePropagation();const form=e.target;if(!form.reportValidity())return;const button=form.querySelector('[type=submit]');button.disabled=true;form.reset();try{await api('subscription',{action:'activate'});modal.close();await refresh();toast('Premium demo activo por 30 días. No se realizó ningún cobro.')}catch(error){toast(error.message);button.disabled=false}});
document.addEventListener('submit',async e=>{const f=e.target;if(!['applicationForm','reviewForm','loginForm','registerForm','adminSetupForm','professionalForm','bookingForm','assignForm','passwordForm','forcedPasswordForm','resetPasswordForm'].includes(f.id))return;e.preventDefault();const button=f.querySelector('button[type="submit"],button:not([type])');if(button)button.disabled=true;const err=f.querySelector('.form-error');if(err)err.textContent='';try{const data=Object.fromEntries(new FormData(f));if('confirmPassword'in data&&data.password!==data.confirmPassword)throw new Error('Las contraseñas no coinciden.');delete data.confirmPassword;if(f.id==='applicationForm'){await api('application',data);modal.close();page='home';await refresh();toast('Postulación enviada para revisión.')}else if(f.id==='reviewForm'){await api(`applications/${f.dataset.id}/review`,{action:f.dataset.action,version:Number(f.dataset.version),reason:data.reason||''});modal.close();await refresh();toast(f.dataset.action==='approve'?'Profesional aprobado.':'Revisión guardada.')}else if(f.id==='loginForm'){await api('login',data);authEpoch++;await boot();broadcastAuth()}else if(f.id==='adminSetupForm'){await api('admin/setup',data);setupToken='';canSetupAdmin=false;authEpoch++;await boot();toast('Tu acceso de administrador está listo.')}else if(f.id==='registerForm'){await api('register',data);authEpoch++;await boot();toast(data.role==='worker'?'Postulación enviada para revisión.':'Tu cuenta de cliente está lista.')}else if(['passwordForm','forcedPasswordForm'].includes(f.id)){await api('password',data);if(modal.open)modal.close();authEpoch++;await boot();toast('Contraseña actualizada.')}else if(f.id==='resetPasswordForm'){await api(`accounts/${f.dataset.id}/password`,data);modal.close();await refresh();toast('Contraseña temporal asignada.')}else if(f.id==='professionalForm'){await api('professionals',data);modal.close();page='team';await refresh();toast('Profesional registrado con contraseña temporal.')}else if(f.id==='bookingForm'){await api('requests',{...data,professional:Number(f.dataset.pro)});modal.close();page='requests';filter='Todos';await refresh();toast('Solicitud creada.')}else if(f.id==='assignForm'){await api(`requests/${f.dataset.id}/assign`,data);modal.close();await refresh();toast('Servicio asignado.')}}catch(error){if(err)err.textContent=error.message;else toast(error.message)}finally{if(button)button.disabled=false}});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;document.querySelector('#pros').innerHTML=matchedPros().map(proCard).join('')||'<div class="empty">No encontramos coincidencias.</div>'}});modal.addEventListener('click',e=>{if(e.target===modal)modal.close()});
// Retire the old offline demo cache. Account data and authenticated HTML are never cached.
if('serviceWorker'in navigator){navigator.serviceWorker.getRegistrations().then(rs=>Promise.all(rs.map(r=>r.unregister()))).catch(()=>{});if('caches'in window)caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('servimatch-shell-')).map(k=>caches.delete(k)))).catch(()=>{})}
boot();

window.addEventListener('storage',e=>{if(e.key==='servimatch-auth-event'){resetUi();boot()}});window.addEventListener('pageshow',e=>{if(e.persisted){resetUi();boot()}});

function premiumActive(){return currentUser?.premiumUntil&&new Date(currentUser.premiumUntil)>new Date()}
function premiumCard(){if(role!=='worker')return '';return `<section class="premium-banner"><span class="eyebrow">MEMBRESÍA · DEMOSTRACIÓN</span><h2><span class="premium-symbol">${icon('crown')}</span><span>ServiMatch Premium</span></h2><p>Haz crecer tus oportunidades</p><strong class="premium-price">$5.99 <small>/ mes</small></strong><p>${premiumActive()?'Demo activa hasta '+new Date(currentUser.premiumUntil).toLocaleDateString('es-SV'):'Descubre una nueva forma de destacar.'}</p><button class="btn" data-premium>${premiumActive()?'Administrar suscripción demo':'Conocer Premium'}</button></section>`}
function premiumDetails(){if(role!=='worker')return;show(`${role==='worker'&&!application?'<button class="btn wide" data-edit-public-profile>Completar mi perfil profesional</button>':''}${premiumCard()}<h3>Beneficios propuestos</h3><div class="premium-benefits"><div class="premium-benefit"><span class="premium-benefit-icon">${icon('trend')}</span><div><b>Mayor visibilidad</b><p>Posiciones destacadas para tu perfil.</p></div></div><div class="premium-benefit"><span class="premium-benefit-icon">${icon('shield')}</span><div><b>Perfil destacado</b><p>Una insignia Premium para diferenciarte.</p></div></div><div class="premium-benefit"><span class="premium-benefit-icon">${icon('chart')}</span><div><b>Estadísticas de tu perfil</b><p>Conocer el interés en tus servicios.</p></div></div><div class="premium-benefit"><span class="premium-benefit-icon">${icon('briefcase')}</span><div><b>Más oportunidades</b><p>Herramientas para conectar con clientes.</p></div></div></div><p class="notice">Esta es una demostración: activa el estado Premium durante 30 días, sin cobros ni renovación automática. Los beneficios anteriores son una propuesta y aún no están habilitados. La aprobación profesional sigue siendo necesaria.</p>${premiumActive()?'<button class="btn outline wide" data-cancel-premium>Cancelar suscripción demo</button>':'<button class="btn wide" data-demo-checkout>Probar activación · $0 de cobro</button>'}`)}
function demoCheckout(){if(role!=='worker')return;show(`<div class="checkout-heading"><span class="checkout-icon">${icon('shield')}</span><div><span class="eyebrow">TU MEMBRESÍA</span><h2>Activa Premium</h2><p class="sub">Un paso más para impulsar tu talento.</p></div></div><div class="checkout-summary"><div class="checkout-plan"><span class="premium-symbol">${icon('crown')}</span><div><strong>ServiMatch Premium</strong><small>Demostración por 30 días</small></div><span class="checkout-pill">DEMO</span></div><div class="checkout-total"><span>Total a cobrar hoy</span><strong>$0.00 <small>USD</small></strong></div><p>Precio de referencia: $5.99 / mes · Sin renovación automática</p></div><form id="demoPaymentForm" class="checkout-form" autocomplete="off"><div class="checkout-section"><h3>Datos de prueba</h3><span>Visa · Mastercard · Amex y otras</span></div><p class="checkout-hint" id="demoPaymentHelp">Usa únicamente datos ficticios. No hay cobro y los campos de pago no se envían ni se guardan.</p><label class="field">Nombre del titular ficticio<input required maxlength="80" placeholder="Ej. Persona de prueba" autocomplete="off"></label><label class="field">Número de tarjeta de prueba<input id="demoCardNumber" required inputmode="numeric" pattern="[0-9 ]{13,23}" maxlength="23" aria-describedby="demoCardBrand demoPaymentHelp" placeholder="4242 4242 4242 4242" autocomplete="off"></label><div class="card-brand" id="demoCardBrand" role="status" aria-live="polite">${icon('shield')}<span>La marca se identifica al escribir</span></div><div class="two"><label class="field">Vencimiento<input id="demoCardExpiry" inputmode="numeric" required pattern="(0[1-9]|1[0-2])/[0-9]{2}" maxlength="5" placeholder="MM/AA" autocomplete="off"></label><label class="field">Código de seguridad<input id="demoCardCode" required type="password" inputmode="numeric" pattern="[0-9]{3,4}" maxlength="4" placeholder="CVV" autocomplete="off"></label></div><button class="btn wide checkout-submit" type="submit">${icon('shield')} Activar demo · $0.00</button><p class="checkout-footnote">Sin cargos reales. Puedes cancelar la demostración desde tu perfil.</p></form>`)}
document.addEventListener('change',async e=>{if(e.target.id!=='profilePhoto')return;const file=e.target.files?.[0];if(!file)return;try{if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>8*1024*1024)throw new Error('Elige una imagen JPG, PNG o WebP de hasta 8 MB.');const bitmap=await createImageBitmap(file);const canvas=document.createElement('canvas');canvas.width=640;canvas.height=640;const ctx=canvas.getContext('2d');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,640,640);const side=Math.min(bitmap.width,bitmap.height);ctx.drawImage(bitmap,(bitmap.width-side)/2,(bitmap.height-side)/2,side,side,0,0,640,640);bitmap.close();let quality=0.88,photo=canvas.toDataURL('image/jpeg',quality);while(photo.length>170000&&quality>0.25){quality-=0.1;photo=canvas.toDataURL('image/jpeg',quality)}await api('profile/photo',{photo});await refresh();toast('Foto de perfil actualizada')}catch(error){toast(error.message)}finally{e.target.value=''}});

modal.addEventListener('close',()=>{if(!modal.open)document.querySelector('#modalBody').textContent=''});

function openPhoto(src,label='Foto de perfil'){
 if(!src||!src.startsWith('data:image/jpeg;base64,'))return;
 const viewer=document.createElement('dialog');viewer.className='photo-viewer';viewer.setAttribute('aria-label',label||'Foto de perfil');
 viewer.innerHTML=`<div class="photo-viewer-heading"><div><span class="eyebrow">FOTO DE PERFIL</span><h2>${esc(label.replace(/^Foto de /,''))}</h2></div><button type="button" class="close photo-viewer-close" aria-label="Cerrar foto">×</button></div><div class="photo-viewer-stage"><img src="${esc(src)}" alt="${esc(label)}"></div><p>Toca fuera de la ventana o pulsa × para volver.</p>`;
 document.body.appendChild(viewer);viewer.querySelector('button').addEventListener('click',()=>viewer.close());viewer.addEventListener('click',e=>{if(e.target===viewer)viewer.close()});viewer.addEventListener('close',()=>viewer.remove());viewer.showModal();
}
function cardBrand(value){
 const digits=value.replace(/\D/g,''),six=Number(digits.slice(0,6));
 if(/^4/.test(digits))return 'Visa';
 if(/^5[1-5]/.test(digits)||(digits.length>=6&&six>=222100&&six<=272099))return 'Mastercard';
 if(/^3[47]/.test(digits))return 'American Express';
 if(/^6011|^65|^64[4-9]/.test(digits))return 'Discover';
 if(digits.length>=4&&Number(digits.slice(0,4))>=3528&&Number(digits.slice(0,4))<=3589)return 'JCB';
 return digits.length<6?'Marca por identificar':'Otra marca';
}
function formatCardNumber(value){const digits=value.replace(/\D/g,'').slice(0,19);return cardBrand(digits)==='American Express'?digits.slice(0,15).replace(/^(\d{4})(\d{0,6})(\d{0,5})$/,(_,a,b,c)=>[a,b,c].filter(Boolean).join(' ')):digits.match(/.{1,4}/g)?.join(' ')||''}
function formatCardExpiry(value){const digits=value.replace(/\D/g,'').slice(0,4);return digits.length>2?digits.slice(0,2)+'/'+digits.slice(2):digits}
document.addEventListener('input',e=>{
 const input=e.target;if(input.id==='demoCardNumber'){
  const digitsBefore=input.value.slice(0,input.selectionStart??input.value.length).replace(/\D/g,'').length;
  input.value=formatCardNumber(input.value);let position=0,count=0;while(position<input.value.length&&count<digitsBefore){if(/\d/.test(input.value[position]))count++;position++}input.setSelectionRange(position,position);
  const brand=cardBrand(input.value);document.querySelector('#demoCardBrand').innerHTML=`${icon('shield')}<span>${esc(brand)} · Identificación orientativa, sin validar fondos</span>`;
  const code=document.querySelector('#demoCardCode');code.maxLength=brand==='American Express'?4:3;code.pattern=brand==='American Express'?'[0-9]{4}':'[0-9]{3}';code.value=code.value.slice(0,code.maxLength);
 }else if(input.id==='demoCardExpiry')input.value=formatCardExpiry(input.value);
 else if(input.id==='demoCardCode')input.value=input.value.replace(/\D/g,'').slice(0,input.maxLength);
});

function trustSummary(p){return `${Number(p.completed||0)} trabajos completados · ${p.reviewCount?Number(p.rating).toFixed(1)+' / 5 ('+Number(p.reviewCount)+' reseñas)':'Sin reseñas aún'}`}
function chatButton(r){if(!r.pro||!['client','worker'].includes(role)||r.redacted)return '';const count=communityData.unread.find(n=>n.request_id===r.id)?.total||0;return `<button class="btn secondary chat-launch" data-chat="${esc(r.id)}">${icon('list')} <span>Chat${count?' · '+count+(count===1?' nuevo':' nuevos'):''}</span></button>`}
function reviewButton(r){return role==='client'&&r.status==='Completado'?communityData.reviewed.some(v=>v.request_id===r.id)?'<span class="badge">Reseña publicada</span>':`<button class="btn" data-review-service="${esc(r.id)}">Calificar servicio</button>`:''}
function publicProfileExtras(data){const d=data.details||{};return `<p class="badge">${icon('shield')} Perfil aprobado por administración</p><p class="sub">La formación y los trabajos del portafolio son información aportada por el profesional.</p><div class="profile-facts">${[['Especialidades',d.specialties],['Horarios de atención',d.schedule],['Formación declarada',d.training],['Tarifas y condiciones',d.conditions]].filter(([,v])=>v).map(([label,value])=>`<section><h3>${label}</h3><p>${esc(value)}</p></section>`).join('')}</div><h3 class="community-title">Trabajos realizados</h3><div class="portfolio-grid">${(d.portfolio||[]).map(item=>`<article><button type="button" class="portfolio-photo" data-view-photo aria-label="Ampliar trabajo: ${esc(item.title)}"><img class="avatar-photo" src="${esc(item.photo)}" alt="${esc(item.title)}" loading="lazy"></button><h3>${esc(item.title)}</h3><p>${esc(item.description)}</p></article>`).join('')||'<p class="sub">Todavía no ha agregado trabajos al portafolio.</p>'}</div><h3 class="community-title">Opiniones de clientes</h3>${data.reviews.map(review=>`<article class="review-entry"><strong>${Number(review.rating)} / 5 · ${esc(review.name)}</strong><small>${new Date(review.created).toLocaleDateString('es-SV')} · Servicio completado</small><p>${esc(review.comment)}</p></article>`).join('')||'<p class="sub">Aún no tiene reseñas de servicios completados.</p>'}`}
let chatSession=0,chatTimer=null,chatLast=0,chatBusy=false;
function stopChat(){chatSession++;if(chatTimer)window.clearInterval(chatTimer);chatTimer=null;chatBusy=false}
modal.addEventListener('close',()=>{if(!modal.open)stopChat()});
async function openChat(id){stopChat();const r=requests.find(r=>r.id===id);if(!r)return;show(`<div class="chat-heading"><span class="eyebrow">CONVERSACIÓN PRIVADA</span><h2>${esc(r.service)}</h2><p class="sub">${role==='client'?esc(pros.find(p=>p.id===r.pro)?.name||'Profesional'):esc(r.client)} · ${shortId(id)}</p></div><p class="chat-privacy">Solo tú y la otra persona de este servicio pueden leer esta conversación. No compartas contraseñas ni datos de pago.</p><div class="chat-messages" id="chatMessages" role="log" aria-label="Mensajes del servicio" aria-live="polite"><p class="sub">Cargando mensajes…</p></div><p id="chatConnection" class="sub" role="status"></p><form id="chatForm" data-id="${esc(id)}" class="chat-compose"><label class="field">Mensaje<textarea name="body" required maxlength="2000" rows="2" placeholder="Escribe para coordinar tu servicio"></textarea></label><button class="btn" type="submit">Enviar</button><div class="form-error" role="alert"></div></form><p class="sub">Se muestran los últimos 100 mensajes. Se actualiza cada 5 segundos mientras el chat está abierto.</p>`);const session=chatSession;chatLast=0;
 const update=async()=>{if(session!==chatSession||!modal.open||document.hidden||chatBusy)return;chatBusy=true;try{const data=await api(`requests/${id}/messages`);if(session!==chatSession)return;const box=document.querySelector('#chatMessages');if(!box)return;const last=data.messages.at(-1)?.id||0;const nearBottom=box.scrollHeight-box.scrollTop-box.clientHeight<70;if(last!==chatLast||chatLast===0){box.innerHTML=data.messages.map(m=>`<article class="chat-bubble ${m.sender_id===currentUser.id?'mine':''}"><strong>${esc(m.name)}</strong><p>${esc(m.body)}</p><time>${new Date(m.created).toLocaleString('es-SV',{timeZone:'America/El_Salvador',dateStyle:'short',timeStyle:'short'})}</time></article>`).join('')||'<p class="chat-empty">Comienza la conversación. Coordina horarios y detalles del servicio aquí.</p>';if(nearBottom||chatLast===0)box.scrollTop=box.scrollHeight;chatLast=last}
 const form=document.querySelector('#chatForm');form.hidden=data.readOnly;document.querySelector('#chatConnection').textContent=data.readOnly?'Servicio cerrado: puedes consultar el historial.':'';
 if(last)await api(`requests/${id}/read`,{lastId:last});communityData.unread=communityData.unread.filter(n=>n.request_id!==id);
 }catch(error){if(session===chatSession){const connection=document.querySelector('#chatConnection');if(connection)connection.textContent=error.message;if(error.status===403||error.status===401)stopChat()}}finally{if(session===chatSession)chatBusy=false}};
 await update();if(session===chatSession)chatTimer=window.setInterval(update,5000);window.refreshChat=update;
}
function reviewService(id){show(`<h2>¿Cómo fue el servicio?</h2><p class="sub">Tu opinión se publicará con tu nombre en el perfil del profesional.</p><form id="serviceReviewForm" data-id="${esc(id)}"><label class="field">Calificación<select name="rating" required><option value="">Selecciona una calificación</option>${[5,4,3,2,1].map(n=>`<option value="${n}">${n} ${n===1?'estrella':'estrellas'}</option>`).join('')}</select></label><label class="field">Tu experiencia<textarea name="comment" required minlength="5" maxlength="1000" placeholder="Cuéntanos cómo realizó el trabajo"></textarea></label><button class="btn wide" type="submit">Publicar reseña</button><div class="form-error" role="alert"></div></form>`)}
let portfolioDraft=[];
async function editPublicProfile(){const p=pros.find(p=>p.mine);if(!p)return;const epoch=authEpoch;const data=await api(`professionals/${p.id}/profile`);if(epoch!==authEpoch)return;const d=data.details;portfolioDraft=(d.portfolio||[]).map(v=>({...v}));show(`<h2>Tu perfil profesional</h2><p class="sub">Explica cómo trabajas y muestra ejemplos reales. No publiques fotos ni datos de clientes sin su permiso.</p><form id="publicProfileForm"><label class="field">Presentación<textarea name="bio" minlength="10" maxlength="1000" required>${esc(p.bio)}</textarea></label><label class="field">Zona<input name="zone" required minlength="2" maxlength="200" value="${esc(p.zone)}"></label><label class="field">Experiencia<input name="experience" required minlength="2" maxlength="500" value="${esc(p.experience)}"></label>${[['specialties','Especialidades concretas',500,'Ej. Reparación de fugas, instalación de sanitarios'],['schedule','Horarios de atención',300,'Ej. Lunes a sábado, de 8:00 a 17:00'],['training','Formación y cursos (sin verificar)',500,'Indica cursos o estudios relevantes'],['conditions','Tarifas y condiciones',500,'Costo de visita, garantía ofrecida y qué incluye']].map(([name,label,max,placeholder])=>`<label class="field">${label}<textarea name="${name}" maxlength="${max}" placeholder="${placeholder}">${esc(d[name]||'')}</textarea></label>`).join('')}<h3 class="community-title">Portafolio · Hasta 6 trabajos</h3><div id="portfolioDraft"></div><button type="button" class="btn secondary" data-add-portfolio>Agregar trabajo</button><p class="sub">Las fotos se comprimen antes de guardarse.</p><button class="btn wide" type="submit">Guardar perfil</button><div class="form-error" role="alert"></div></form>`);renderPortfolioDraft()}
function renderPortfolioDraft(){const root=document.querySelector('#portfolioDraft');if(!root)return;root.innerHTML=portfolioDraft.map((item,i)=>`<section class="portfolio-editor"><img src="${esc(item.photo)}" alt="Trabajo ${i+1}"><div><label class="field">Título<input data-portfolio-title="${i}" value="${esc(item.title)}" required minlength="3" maxlength="100"></label><label class="field">Descripción<textarea data-portfolio-description="${i}" maxlength="500">${esc(item.description)}</textarea></label><button class="text-button" type="button" data-remove-portfolio="${i+1}">Quitar trabajo</button></div></section>`).join('')}
function addPortfolioItem(){if(portfolioDraft.length>=6){toast('Puedes agregar hasta seis trabajos.');return}const input=document.createElement('input');input.type='file';input.accept='image/jpeg,image/png,image/webp';input.addEventListener('change',async()=>{try{const file=input.files?.[0];if(!file)return;const photo=await compressPortfolioPhoto(file);if(!document.querySelector('#publicProfileForm'))return;portfolioDraft.push({title:'',description:'',photo});renderPortfolioDraft()}catch(error){toast(error.message)}});input.click()}
async function compressPortfolioPhoto(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>8*1024*1024)throw new Error('Elige JPG, PNG o WebP de hasta 8 MB.');const bitmap=await createImageBitmap(file);const scale=Math.min(1,900/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();let quality=.85,photo=canvas.toDataURL('image/jpeg',quality);while(photo.length>170000&&quality>.2){quality-=.1;photo=canvas.toDataURL('image/jpeg',quality)}return photo}
document.addEventListener('input',e=>{if(e.target.dataset.portfolioTitle!==undefined)portfolioDraft[Number(e.target.dataset.portfolioTitle)].title=e.target.value;if(e.target.dataset.portfolioDescription!==undefined)portfolioDraft[Number(e.target.dataset.portfolioDescription)].description=e.target.value});
document.addEventListener('submit',async e=>{const f=e.target;if(!['chatForm','publicProfileForm','serviceReviewForm'].includes(f.id))return;e.preventDefault();const button=f.querySelector('[type=submit]'),error=f.querySelector('.form-error'),epoch=authEpoch;button.disabled=true;error.textContent='';try{const data=Object.fromEntries(new FormData(f));if(f.id==='chatForm'){await api(`requests/${f.dataset.id}/messages`,{body:data.body});if(epoch!==authEpoch)return;f.reset();await window.refreshChat?.()}else if(f.id==='publicProfileForm'){await api('professional/profile',{...data,portfolio:portfolioDraft});if(epoch!==authEpoch)return;modal.close();await refresh();toast('Perfil profesional actualizado.')}else{await api(`requests/${f.dataset.id}/review`,{rating:Number(data.rating),comment:data.comment});if(epoch!==authEpoch)return;modal.close();await refresh();toast('Gracias. Tu reseña está publicada.')}}catch(err){error.textContent=err.message}finally{button.disabled=false}});
if(window.setInterval)window.setInterval(async()=>{if(!currentUser||!['client','worker'].includes(role)||application||document.hidden||modal.open)return;const epoch=authEpoch;try{const data=await api('state');if(epoch!==authEpoch)return;communityData=data.community||communityData;document.querySelectorAll('[data-chat]').forEach(b=>{const n=communityData.unread.find(v=>v.request_id===b.dataset.chat)?.total||0;b.innerHTML=`${icon('list')} <span>Chat${n?' · '+n+(n===1?' nuevo':' nuevos'):''}</span>`})}catch{}},20000);
